String getClosestVowel(String word) {
  if (word.length < 3) {
    return "";
  }

  Set<String> vowels = {"a", "e", "i", "o", "u", "A", "E", "O", "U", "I"};

  for (int i = word.length - 2; i > 0; i--) {
    if (vowels.contains(word[i])) {
      if (!vowels.contains(word[i + 1]) && !vowels.contains(word[i - 1])) {
        return word[i];
      }
    }
  }

  return "";
}

